arguments.file_text:
@page "/settings"
@using sv_2f2a6ab1bbee47588de68a7fd4000fc3.Models
@using sv_2f2a6ab1bbee47588de68a7fd4000fc3.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar" aria-label="Settings sections">
        <h5 class="sidebar-title">Settings</h5>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_statusMessage is not null)
        {
            <div class="toast-message @(_statusIsError ? "toast-error" : "toast-success")" role="alert">
                @_statusMessage
                <button class="toast-close" @onclick="DismissToast">&times;</button>
            </div>
        }

        @switch (_activeSection)
        {
            case "Profile":
                @RenderProfile()
                break;
            case "Notifications":
                @RenderNotifications()
                break;
            case "Security":
                @RenderSecurity()
                break;
            case "Appearance":
                @RenderAppearance()
                break;
        }
    </div>
</div>

@* ── Confirmation Modal ── *@
@if (_showConfirmDialog)
{
    <div class="modal-backdrop" @onclick="CancelConfirm">
        <div class="confirm-dialog" @onclick:stopPropagation>
            <h6>@_confirmTitle</h6>
            <p>@_confirmMessage</p>
            <div class="confirm-actions">
                <button class="btn btn-secondary btn-sm" @onclick="CancelConfirm">Cancel</button>
                <button class="btn btn-danger btn-sm" @onclick="ExecuteConfirm">Confirm</button>
            </div>
        </div>
    </div>
}

@* ───────────────── PROFILE SECTION ───────────────── *@
@{
    RenderFragment RenderProfile() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Profile</h4>

            @if (_profile is not null)
            {
                <div class="profile-layout">
                    <div class="avatar-area">
                        <img src="@_editAvatarUrl" alt="Avatar" class="avatar-preview" />
                        <div class="form-group mt-2">
                            <label class="form-label">Avatar URL</label>
                            <input class="form-control form-control-sm" @bind="_editAvatarUrl" />
                        </div>
                    </div>

                    <div class="profile-fields">
                        <div class="form-group">
                            <label class="form-label">Display Name</label>
                            <input class="form-control" @bind="_editDisplayName" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Email</label>
                            <input class="form-control" type="email" @bind="_editEmail" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Bio</label>
                            <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_isSaving">
                                @(_isSaving ? "Saving…" : "Save Changes")
                            </button>
                            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                                Discard Changes
                            </button>
                        </div>
                    </div>
                </div>
            }
            else
            {
                <p class="text-muted">Loading profile…</p>
            }
        </section>
    };
}

@* ───────────────── NOTIFICATIONS SECTION ───────────────── *@
@{
    RenderFragment RenderNotifications() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Notifications</h4>

            @if (_notifPrefs is not null)
            {
                <div class="toggle-list">
                    <div class="toggle-item">
                        <label class="toggle-label">Email Notifications</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editEmailNotif" />
                        </div>
                    </div>
                    <div class="toggle-item">
                        <label class="toggle-label">Push Notifications</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editPushNotif" />
                        </div>
                    </div>
                    <div class="toggle-item">
                        <label class="toggle-label">Weekly Digest</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editWeeklyDigest" />
                        </div>
                    </div>
                </div>

                <h6 class="mt-4">Muted Channels</h6>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var ch = channel;
                        <div class="form-check">
                            <input class="form-check-input darker-border-checkbox" type="checkbox"
                                   id="@($"ch-{ch}")"
                                   checked="@_editMutedChannels.Contains(ch)"
                                   @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                            <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
                        </div>
                    }
                </div>

                <div class="button-group mt-4">
                    <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_isSaving">
                        @(_isSaving ? "Saving…" : "Save Preferences")
                    </button>
                </div>
            }
            else
            {
                <p class="text-muted">Loading notification preferences…</p>
            }
        </section>
    };
}

@* ───────────────── SECURITY SECTION ───────────────── *@
@{
    RenderFragment RenderSecurity() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Security</h4>

            @* Change Password Panel *@
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">&#9660;</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label class="form-label">Current Password</label>
                            <input class="form-control" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">New Password</label>
                            <input class="form-control" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Confirm New Password</label>
                            <input class="form-control" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary btn-sm mt-2" @onclick="ChangePassword" disabled="@_isSaving">
                            Update Password
                        </button>
                    </div>
                }
            </div>

            @* Two-Factor *@
            @if (_securitySettings is not null)
            {
                <div class="toggle-item mt-4">
                    <div>
                        <label class="toggle-label">Two-Factor Authentication</label>
                        <span class="badge @(_editTwoFactor ? "bg-success" : "bg-secondary") ms-2">
                            @(_editTwoFactor ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch"
                               @bind="_editTwoFactor" />
                    </div>
                </div>

                @if (_securitySettings.LastPasswordChange is not null)
                {
                    <p class="text-muted mt-2 mb-0" style="font-size: .85rem;">
                        Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </p>
                }

                @* Active Sessions *@
                <h6 class="mt-4">Active Sessions</h6>
                <div class="table-responsive">
                    <table class="table table-sm table-bordered align-middle">
                        <thead class="table-light">
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th style="width:100px"></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var isCurrentSession = session.Id == _securitySettings.Sessions[0].Id;
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrentSession)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">Loading security settings…</p>
            }
        </section>
    };
}

@* ───────────────── APPEARANCE SECTION ───────────────── *@
@{
    RenderFragment RenderAppearance() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Appearance</h4>

            <div class="appearance-grid">
                <div class="appearance-controls">
                    @* Theme *@
                    <fieldset class="form-group">
                        <legend class="form-label">Theme</legend>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            var t = theme;
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{t}")"
                                       checked="@(_editTheme == t)"
                                       @onchange="() => _editTheme = t" />
                                <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                            </div>
                        }
                    </fieldset>

                    @* Font Size *@
                    <fieldset class="form-group">
                        <legend class="form-label">Font Size</legend>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            var s = size;
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{s}")"
                                       checked="@(_editFontSize == s)"
                                       @onchange="() => _editFontSize = s" />
                                <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                            </div>
                        }
                    </fieldset>

                    @* Language *@
                    <div class="form-group">
                        <label class="form-label">Language</label>
                        <select class="form-select" @bind="_editLanguage">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>

                    @* Compact Mode *@
                    <div class="toggle-item">
                        <label class="toggle-label">Compact Mode</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editCompactMode" />
                        </div>
                    </div>

                    <div class="button-group mt-3">
                        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_isSaving">
                            @(_isSaving ? "Saving…" : "Save")
                        </button>
                    </div>
                </div>

                @* Live Preview *@
                <div class="preview-area @GetPreviewClasses()">
                    <div class="preview-card">
                        <h6 class="preview-heading">Live Preview</h6>
                        <p class="preview-text">
                            This is how your content will look with the selected settings.
                        </p>
                        <div class="preview-meta">
                            <span class="badge bg-primary me-1">@_editTheme</span>
                            <span class="badge bg-secondary me-1">@_editFontSize</span>
                            <span class="badge bg-info">@_editLanguage</span>
                        </div>
                        <div class="preview-sample-row mt-2">
                            <button class="btn btn-primary btn-sm">Primary</button>
                            <button class="btn btn-outline-secondary btn-sm">Secondary</button>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    };
}

@code {
    // ── Section navigation ──
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";

    // ── Toast state ──
    private string? _statusMessage;
    private bool _statusIsError;

    // ── Shared ──
    private bool _isSaving;

    // ── Profile ──
    private UserProfile? _profile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";

    // ── Notifications ──
    private NotificationPrefs? _notifPrefs;
    private bool _editEmailNotif;
    private bool _editPushNotif;
    private bool _editWeeklyDigest;
    private HashSet<string> _editMutedChannels = [];
    private readonly List<string> _allChannels = InMemorySettingsService.GetAllChannels();

    // ── Security ──
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _editTwoFactor;

    // ── Appearance ──
    private AppearanceSettings? _appearance;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    // ── Confirm dialog ──
    private bool _showConfirmDialog;
    private string _confirmTitle = "";
    private string _confirmMessage = "";
    private Func<Task>? _confirmAction;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    // ── Navigation ──

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        DismissToast();
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (_activeSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                PopulateProfileFields(_profile);
                break;
            case "Notifications":
                _notifPrefs = await SettingsService.GetNotificationPrefsAsync();
                PopulateNotifFields(_notifPrefs);
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                _editTwoFactor = _securitySettings.TwoFactorEnabled;
                break;
            case "Appearance":
                _appearance = await SettingsService.GetAppearanceAsync();
                PopulateAppearanceFields(_appearance);
                break;
        }
    }

    // ── Profile ──

    private void PopulateProfileFields(UserProfile p)
    {
        _editDisplayName = p.DisplayName;
        _editEmail = p.Email;
        _editAvatarUrl = p.AvatarUrl;
        _editBio = p.Bio;
    }

    private async Task SaveProfile()
    {
        _isSaving = true;
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _isSaving = false;
        ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
            PopulateProfileFields(_profile);

        ShowToast("Changes discarded.");
    }

    // ── Notifications ──

    private void PopulateNotifFields(NotificationPrefs prefs)
    {
        _editEmailNotif = prefs.EmailNotifications;
        _editPushNotif = prefs.PushNotifications;
        _editWeeklyDigest = prefs.WeeklyDigest;
        _editMutedChannels = [.. prefs.MutedChannels];
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _editMutedChannels.Add(channel);
        else
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _isSaving = true;
        var updated = new NotificationPrefs(
            _editEmailNotif, _editPushNotif, _editWeeklyDigest,
            _editMutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notifPrefs = updated;
        _isSaving = false;
        ShowToast("Notification preferences saved.");
    }

    // ── Security ──

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword)
            || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", isError: true);
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", isError: true);
            return;
        }

        _isSaving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = _newPassword = _confirmPassword = "";
        _passwordPanelOpen = false;
        _isSaving = false;
        ShowToast("Password updated successfully.");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _confirmTitle = "Revoke Session";
        _confirmMessage = $"Are you sure you want to revoke the session on \"{session.Device}\" in {session.Location}?";
        _confirmAction = async () =>
        {
            await SettingsService.RevokeSessionAsync(session.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.");
        };
        _showConfirmDialog = true;
    }

    private async Task ExecuteConfirm()
    {
        _showConfirmDialog = false;
        if (_confirmAction is not null)
            await _confirmAction();
    }

    private void CancelConfirm() => _showConfirmDialog = false;

    // ── Appearance ──

    private void PopulateAppearanceFields(AppearanceSettings a)
    {
        _editTheme = a.Theme;
        _editFontSize = a.FontSize;
        _editLanguage = a.Language;
        _editCompactMode = a.CompactMode;
    }

    private async Task SaveAppearance()
    {
        _isSaving = true;
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        _isSaving = false;
        ShowToast("Appearance settings saved.");
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_editTheme == "Dark" ? "preview-dark" : "preview-light");
        classes.Add($"preview-font-{_editFontSize.ToLowerInvariant()}");
        if (_editCompactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    // ── Helpers ──

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private void ShowToast(string message, bool isError = false)
    {
        _statusMessage = message;
        _statusIsError = isError;
    }

    private void DismissToast() => _statusMessage = null;
}

/* ── Settings Dashboard Layout ── */

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    background: #fff;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.65rem 1.25rem;
    border: none;
    background: transparent;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: #e9ecef;
}

.sidebar-item.active {
    background: #fff;
    color: #0d6efd;
    font-weight: 600;
    border-right: 3px solid #0d6efd;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h4 {
    margin-bottom: 1.25rem;
    font-weight: 600;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group legend.form-label {
    font-size: 0.9rem;
    float: none;
    width: auto;
    padding: 0;
}

.button-group {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

/* ── Toast / Status Message ── */

.toast-message {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    animation: slideIn 0.25s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: transparent;
    border: none;
    font-size: 1.2rem;
    line-height: 1;
    cursor: pointer;
    opacity: 0.6;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-8px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Profile ── */

.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    text-align: center;
    flex-shrink: 0;
    width: 180px;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.profile-fields {
    flex: 1;
    max-width: 500px;
}

/* ── Toggle Items ── */

.toggle-list {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    font-weight: 500;
    margin: 0;
}

/* ── Channels ── */

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 0.25rem 1rem;
}

/* ── Expandable Panel ── */

.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.95rem;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-chevron {
    font-size: 0.7rem;
    transition: transform 0.2s;
}

.panel-chevron.open {
    transform: rotate(180deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
    max-width: 400px;
}

/* ── Confirmation Dialog ── */

.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

.confirm-dialog {
    background: #fff;
    border-radius: 0.5rem;
    padding: 1.5rem;
    min-width: 360px;
    max-width: 90vw;
    box-shadow: 0 8px 30px rgba(0,0,0,0.2);
}

.confirm-dialog h6 {
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.confirm-dialog p {
    color: #6c757d;
    font-size: 0.9rem;
}

.confirm-actions {
    display: flex;
    gap: 0.5rem;
    justify-content: flex-end;
    margin-top: 1rem;
}

/* ── Appearance ── */

.appearance-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.appearance-controls fieldset {
    border: none;
    padding: 0;
    margin: 0 0 1rem 0;
}

/* ── Live Preview ── */

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
    align-self: start;
}

.preview-card {
    transition: all 0.3s ease;
}

.preview-heading {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    color: #6c757d;
    margin-bottom: 0.75rem;
}

.preview-meta {
    margin-bottom: 0.5rem;
}

.preview-sample-row {
    display: flex;
    gap: 0.5rem;
}

/* Preview theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-text {
    color: #adb5bd;
}

.preview-dark .preview-heading {
    color: #f0f0f0;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

/* Compact mode preview */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-text {
    margin-bottom: 0.35rem;
}

.preview-compact .preview-heading {
    margin-bottom: 0.25rem;
}

/* ── Responsive ── */

@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        min-width: unset;
        flex-direction: row;
        overflow-x: auto;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
        padding: 0;
    }

    .sidebar-title {
        display: none;
    }

    .sidebar-item {
        white-space: nowrap;
        padding: 0.75rem 1rem;
        border-right: none !important;
    }

    .sidebar-item.active {
        border-bottom: 3px solid #0d6efd;
        border-right: none !important;
    }

    .profile-layout {
        flex-direction: column;
    }

    .appearance-grid {
        grid-template-columns: 1fr;
    }
}

@page "/settings"
@using sv_2f2a6ab1bbee47588de68a7fd4000fc3.Models
@using sv_2f2a6ab1bbee47588de68a7fd4000fc3.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar" aria-label="Settings sections">
        <h5 class="sidebar-title">Settings</h5>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_statusMessage is not null)
        {
            <div class="toast-message @(_statusIsError ? "toast-error" : "toast-success")" role="alert">
                @_statusMessage
                <button class="toast-close" @onclick="DismissToast">&times;</button>
            </div>
        }

        @switch (_activeSection)
        {
            case "Profile":
                @RenderProfile()
                break;
            case "Notifications":
                @RenderNotifications()
                break;
            case "Security":
                @RenderSecurity()
                break;
            case "Appearance":
                @RenderAppearance()
                break;
        }
    </div>
</div>

@* ── Confirmation Modal ── *@
@if (_showConfirmDialog)
{
    <div class="modal-backdrop" @onclick="CancelConfirm">
        <div class="confirm-dialog" @onclick:stopPropagation>
            <h6>@_confirmTitle</h6>
            <p>@_confirmMessage</p>
            <div class="confirm-actions">
                <button class="btn btn-secondary btn-sm" @onclick="CancelConfirm">Cancel</button>
                <button class="btn btn-danger btn-sm" @onclick="ExecuteConfirm">Confirm</button>
            </div>
        </div>
    </div>
}

@* ───────────────── PROFILE SECTION ───────────────── *@
@{
    RenderFragment RenderProfile() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Profile</h4>

            @if (_profile is not null)
            {
                <div class="profile-layout">
                    <div class="avatar-area">
                        <img src="@_editAvatarUrl" alt="Avatar" class="avatar-preview" />
                        <div class="form-group mt-2">
                            <label class="form-label">Avatar URL</label>
                            <input class="form-control form-control-sm" @bind="_editAvatarUrl" />
                        </div>
                    </div>

                    <div class="profile-fields">
                        <div class="form-group">
                            <label class="form-label">Display Name</label>
                            <input class="form-control" @bind="_editDisplayName" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Email</label>
                            <input class="form-control" type="email" @bind="_editEmail" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Bio</label>
                            <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
                        </div>

                        <div class="button-group">
                            <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_isSaving">
                                @(_isSaving ? "Saving…" : "Save Changes")
                            </button>
                            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                                Discard Changes
                            </button>
                        </div>
                    </div>
                </div>
            }
            else
            {
                <p class="text-muted">Loading profile…</p>
            }
        </section>
    };
}

@* ───────────────── NOTIFICATIONS SECTION ───────────────── *@
@{
    RenderFragment RenderNotifications() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Notifications</h4>

            @if (_notifPrefs is not null)
            {
                <div class="toggle-list">
                    <div class="toggle-item">
                        <label class="toggle-label">Email Notifications</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editEmailNotif" />
                        </div>
                    </div>
                    <div class="toggle-item">
                        <label class="toggle-label">Push Notifications</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editPushNotif" />
                        </div>
                    </div>
                    <div class="toggle-item">
                        <label class="toggle-label">Weekly Digest</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editWeeklyDigest" />
                        </div>
                    </div>
                </div>

                <h6 class="mt-4">Muted Channels</h6>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var ch = channel;
                        <div class="form-check">
                            <input class="form-check-input darker-border-checkbox" type="checkbox"
                                   id="@($"ch-{ch}")"
                                   checked="@_editMutedChannels.Contains(ch)"
                                   @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                            <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
                        </div>
                    }
                </div>

                <div class="button-group mt-4">
                    <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_isSaving">
                        @(_isSaving ? "Saving…" : "Save Preferences")
                    </button>
                </div>
            }
            else
            {
                <p class="text-muted">Loading notification preferences…</p>
            }
        </section>
    };
}

@* ───────────────── SECURITY SECTION ───────────────── *@
@{
    RenderFragment RenderSecurity() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Security</h4>

            @* Change Password Panel *@
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">&#9660;</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label class="form-label">Current Password</label>
                            <input class="form-control" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">New Password</label>
                            <input class="form-control" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label class="form-label">Confirm New Password</label>
                            <input class="form-control" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary btn-sm mt-2" @onclick="ChangePassword" disabled="@_isSaving">
                            Update Password
                        </button>
                    </div>
                }
            </div>

            @* Two-Factor *@
            @if (_securitySettings is not null)
            {
                <div class="toggle-item mt-4">
                    <div>
                        <label class="toggle-label">Two-Factor Authentication</label>
                        <span class="badge @(_editTwoFactor ? "bg-success" : "bg-secondary") ms-2">
                            @(_editTwoFactor ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch"
                               @bind="_editTwoFactor" />
                    </div>
                </div>

                @if (_securitySettings.LastPasswordChange is not null)
                {
                    <p class="text-muted mt-2 mb-0" style="font-size: .85rem;">
                        Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </p>
                }

                @* Active Sessions *@
                <h6 class="mt-4">Active Sessions</h6>
                <div class="table-responsive">
                    <table class="table table-sm table-bordered align-middle">
                        <thead class="table-light">
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th style="width:100px"></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var isCurrentSession = session.Id == _securitySettings.Sessions[0].Id;
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrentSession)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">Loading security settings…</p>
            }
        </section>
    };
}

@* ───────────────── APPEARANCE SECTION ───────────────── *@
@{
    RenderFragment RenderAppearance() => __builder2 =>
    {
        <section class="settings-section">
            <h4>Appearance</h4>

            <div class="appearance-grid">
                <div class="appearance-controls">
                    @* Theme *@
                    <fieldset class="form-group">
                        <legend class="form-label">Theme</legend>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            var t = theme;
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{t}")"
                                       checked="@(_editTheme == t)"
                                       @onchange="() => _editTheme = t" />
                                <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                            </div>
                        }
                    </fieldset>

                    @* Font Size *@
                    <fieldset class="form-group">
                        <legend class="form-label">Font Size</legend>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            var s = size;
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{s}")"
                                       checked="@(_editFontSize == s)"
                                       @onchange="() => _editFontSize = s" />
                                <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                            </div>
                        }
                    </fieldset>

                    @* Language *@
                    <div class="form-group">
                        <label class="form-label">Language</label>
                        <select class="form-select" @bind="_editLanguage">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>

                    @* Compact Mode *@
                    <div class="toggle-item">
                        <label class="toggle-label">Compact Mode</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   @bind="_editCompactMode" />
                        </div>
                    </div>

                    <div class="button-group mt-3">
                        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_isSaving">
                            @(_isSaving ? "Saving…" : "Save")
                        </button>
                    </div>
                </div>

                @* Live Preview *@
                <div class="preview-area @GetPreviewClasses()">
                    <div class="preview-card">
                        <h6 class="preview-heading">Live Preview</h6>
                        <p class="preview-text">
                            This is how your content will look with the selected settings.
                        </p>
                        <div class="preview-meta">
                            <span class="badge bg-primary me-1">@_editTheme</span>
                            <span class="badge bg-secondary me-1">@_editFontSize</span>
                            <span class="badge bg-info">@_editLanguage</span>
                        </div>
                        <div class="preview-sample-row mt-2">
                            <button class="btn btn-primary btn-sm">Primary</button>
                            <button class="btn btn-outline-secondary btn-sm">Secondary</button>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    };
}

@code {
    // ── Section navigation ──
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";

    // ── Toast state ──
    private string? _statusMessage;
    private bool _statusIsError;

    // ── Shared ──
    private bool _isSaving;

    // ── Profile ──
    private UserProfile? _profile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editAvatarUrl = "";
    private string _editBio = "";

    // ── Notifications ──
    private NotificationPrefs? _notifPrefs;
    private bool _editEmailNotif;
    private bool _editPushNotif;
    private bool _editWeeklyDigest;
    private HashSet<string> _editMutedChannels = [];
    private readonly List<string> _allChannels = InMemorySettingsService.GetAllChannels();

    // ── Security ──
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _editTwoFactor;

    // ── Appearance ──
    private AppearanceSettings? _appearance;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    // ── Confirm dialog ──
    private bool _showConfirmDialog;
    private string _confirmTitle = "";
    private string _confirmMessage = "";
    private Func<Task>? _confirmAction;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    // ── Navigation ──

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        DismissToast();
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (_activeSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                PopulateProfileFields(_profile);
                break;
            case "Notifications":
                _notifPrefs = await SettingsService.GetNotificationPrefsAsync();
                PopulateNotifFields(_notifPrefs);
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                _editTwoFactor = _securitySettings.TwoFactorEnabled;
                break;
            case "Appearance":
                _appearance = await SettingsService.GetAppearanceAsync();
                PopulateAppearanceFields(_appearance);
                break;
        }
    }

    // ── Profile ──

    private void PopulateProfileFields(UserProfile p)
    {
        _editDisplayName = p.DisplayName;
        _editEmail = p.Email;
        _editAvatarUrl = p.AvatarUrl;
        _editBio = p.Bio;
    }

    private async Task SaveProfile()
    {
        _isSaving = true;
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _isSaving = false;
        ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
            PopulateProfileFields(_profile);

        ShowToast("Changes discarded.");
    }

    // ── Notifications ──

    private void PopulateNotifFields(NotificationPrefs prefs)
    {
        _editEmailNotif = prefs.EmailNotifications;
        _editPushNotif = prefs.PushNotifications;
        _editWeeklyDigest = prefs.WeeklyDigest;
        _editMutedChannels = [.. prefs.MutedChannels];
    }

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _editMutedChannels.Add(channel);
        else
            _editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _isSaving = true;
        var updated = new NotificationPrefs(
            _editEmailNotif, _editPushNotif, _editWeeklyDigest,
            _editMutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notifPrefs = updated;
        _isSaving = false;
        ShowToast("Notification preferences saved.");
    }

    // ── Security ──

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword)
            || string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please fill in all password fields.", isError: true);
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            ShowToast("New passwords do not match.", isError: true);
            return;
        }

        _isSaving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = _newPassword = _confirmPassword = "";
        _passwordPanelOpen = false;
        _isSaving = false;
        ShowToast("Password updated successfully.");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _confirmTitle = "Revoke Session";
        _confirmMessage = $"Are you sure you want to revoke the session on \"{session.Device}\" in {session.Location}?";
        _confirmAction = async () =>
        {
            await SettingsService.RevokeSessionAsync(session.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.");
        };
        _showConfirmDialog = true;
    }

    private async Task ExecuteConfirm()
    {
        _showConfirmDialog = false;
        if (_confirmAction is not null)
            await _confirmAction();
    }

    private void CancelConfirm() => _showConfirmDialog = false;

    // ── Appearance ──

    private void PopulateAppearanceFields(AppearanceSettings a)
    {
        _editTheme = a.Theme;
        _editFontSize = a.FontSize;
        _editLanguage = a.Language;
        _editCompactMode = a.CompactMode;
    }

    private async Task SaveAppearance()
    {
        _isSaving = true;
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        _isSaving = false;
        ShowToast("Appearance settings saved.");
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_editTheme == "Dark" ? "preview-dark" : "preview-light");
        classes.Add($"preview-font-{_editFontSize.ToLowerInvariant()}");
        if (_editCompactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    // ── Helpers ──

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private void ShowToast(string message, bool isError = false)
    {
        _statusMessage = message;
        _statusIsError = isError;
    }

    private void DismissToast() => _statusMessage = null;
}

/* ── Settings Dashboard Layout ── */

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    background: #fff;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.65rem 1.25rem;
    border: none;
    background: transparent;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: #e9ecef;
}

.sidebar-item.active {
    background: #fff;
    color: #0d6efd;
    font-weight: 600;
    border-right: 3px solid #0d6efd;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h4 {
    margin-bottom: 1.25rem;
    font-weight: 600;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group legend.form-label {
    font-size: 0.9rem;
    float: none;
    width: auto;
    padding: 0;
}

.button-group {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

/* ── Toast / Status Message ── */

.toast-message {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    animation: slideIn 0.25s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: transparent;
    border: none;
    font-size: 1.2rem;
    line-height: 1;
    cursor: pointer;
    opacity: 0.6;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-8px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Profile ── */

.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    text-align: center;
    flex-shrink: 0;
    width: 180px;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.profile-fields {
    flex: 1;
    max-width: 500px;
}

/* ── Toggle Items ── */

.toggle-list {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    font-weight: 500;
    margin: 0;
}

/* ── Channels ── */

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 0.25rem 1rem;
}

/* ── Expandable Panel ── */

.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.95rem;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-chevron {
    font-size: 0.7rem;
    transition: transform 0.2s;
}

.panel-chevron.open {
    transform: rotate(180deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
    max-width: 400px;
}

/* ── Confirmation Dialog ── */

.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

.confirm-dialog {
    background: #fff;
    border-radius: 0.5rem;
    padding: 1.5rem;
    min-width: 360px;
    max-width: 90vw;
    box-shadow: 0 8px 30px rgba(0,0,0,0.2);
}

.confirm-dialog h6 {
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.confirm-dialog p {
    color: #6c757d;
    font-size: 0.9rem;
}

.confirm-actions {
    display: flex;
    gap: 0.5rem;
    justify-content: flex-end;
    margin-top: 1rem;
}

/* ── Appearance ── */

.appearance-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.appearance-controls fieldset {
    border: none;
    padding: 0;
    margin: 0 0 1rem 0;
}

/* ── Live Preview ── */

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
    align-self: start;
}

.preview-card {
    transition: all 0.3s ease;
}

.preview-heading {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    color: #6c757d;
    margin-bottom: 0.75rem;
}

.preview-meta {
    margin-bottom: 0.5rem;
}

.preview-sample-row {
    display: flex;
    gap: 0.5rem;
}

/* Preview theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-text {
    color: #adb5bd;
}

.preview-dark .preview-heading {
    color: #f0f0f0;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

/* Compact mode preview */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-text {
    margin-bottom: 0.35rem;
}

.preview-compact .preview-heading {
    margin-bottom: 0.25rem;
}

/* ── Responsive ── */

@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        min-width: unset;
        flex-direction: row;
        overflow-x: auto;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
        padding: 0;
    }

    .sidebar-title {
        display: none;
    }

    .sidebar-item {
        white-space: nowrap;
        padding: 0.75rem 1rem;
        border-right: none !important;
    }

    .sidebar-item.active {
        border-bottom: 3px solid #0d6efd;
        border-right: none !important;
    }

    .profile-layout {
        flex-direction: column;
    }

    .appearance-grid {
        grid-template-columns: 1fr;
    }
}

