{"file_text": "/* ── Settings Dashboard Layout ── */

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    background: #fff;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.65rem 1.25rem;
    border: none;
    background: transparent;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: #e9ecef;
}

.sidebar-item.active {
    background: #fff;
    color: #0d6efd;
    font-weight: 600;
    border-right: 3px solid #0d6efd;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* ── Content Area ── */

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h4 {
    margin-bottom: 1.25rem;
    font-weight: 600;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group legend.form-label {
    font-size: 0.9rem;
    float: none;
    width: auto;
    padding: 0;
}

.button-group {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

/* ── Toast / Status Message ── */

.toast-message {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    animation: slideIn 0.25s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: transparent;
    border: none;
    font-size: 1.2rem;
    line-height: 1;
    cursor: pointer;
    opacity: 0.6;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-8px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Profile ── */

.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    text-align: center;
    flex-shrink: 0;
    width: 180px;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.profile-fields {
    flex: 1;
    max-width: 500px;
}

/* ── Toggle Items ── */

.toggle-list {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    font-weight: 500;
    margin: 0;
}

/* ── Channels ── */

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 0.25rem 1rem;
}

/* ── Expandable Panel ── */

.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.95rem;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-chevron {
    font-size: 0.7rem;
    transition: transform 0.2s;
}

.panel-chevron.open {
    transform: rotate(180deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
    max-width: 400px;
}

/* ── Confirmation Dialog ── */

.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

.confirm-dialog {
    background: #fff;
    border-radius: 0.5rem;
    padding: 1.5rem;
    min-width: 360px;
    max-width: 90vw;
    box-shadow: 0 8px 30px rgba(0,0,0,0.2);
}

.confirm-dialog h6 {
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.confirm-dialog p {
    color: #6c757d;
    font-size: 0.9rem;
}

.confirm-actions {
    display: flex;
    gap: 0.5rem;
    justify-content: flex-end;
    margin-top: 1rem;
}

/* ── Appearance ── */

.appearance-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.appearance-controls fieldset {
    border: none;
    padding: 0;
    margin: 0 0 1rem 0;
}

/* ── Live Preview ── */

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
    transition: all 0.3s ease;
    align-self: start;
}

.preview-card {
    transition: all 0.3s ease;
}

.preview-heading {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-text {
    color: #6c757d;
    margin-bottom: 0.75rem;
}

.preview-meta {
    margin-bottom: 0.5rem;
}

.preview-sample-row {
    display: flex;
    gap: 0.5rem;
}

/* Preview theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-text {
    color: #adb5bd;
}

.preview-dark .preview-heading {
    color: #f0f0f0;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

/* Compact mode preview */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-text {
    margin-bottom: 0.35rem;
}

.preview-compact .preview-heading {
    margin-bottom: 0.25rem;
}

/* ── Responsive ── */

@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        min-width: unset;
        flex-direction: row;
        overflow-x: auto;
        border-right: none;
        border-bottom: 1px solid #dee2e6;
        padding: 0;
    }

    .sidebar-title {
        display: none;
    }

    .sidebar-item {
        white-space: nowrap;
        padding: 0.75rem 1rem;
        border-right: none !important;
    }

    .sidebar-item.active {
        border-bottom: 3px solid #0d6efd;
        border-right: none !important;
    }

    .profile-layout {
        flex-direction: column;
    }

    .appearance-grid {
        grid-template-columns: 1fr;
    }
}
