@page "/settings"
@using sv_2f2a6ab1bbee47588de68a7fd4000fc3.Models
@using sv_2f2a6ab1bbee47588de68a7fd4000fc3.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar" aria-label="Settings sections">
        <h5 class="sidebar-title">Settings</h5>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                <span class="sidebar-icon">@GetSectionIcon(section)</span>
                @section
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_statusMessage is not null)
        {
            <div class="toast-message @(_statusIsError ? "toast-error" : "toast-success")" role="alert">
                @_statusMessage
                <button class="toast-close" @onclick="DismissToast">&times;</button>
            </div>
        }

        @switch (_activeSection)
        {
            case "Profile":
                @RenderProfile()
                break;
            case "Notifications":
                @RenderNotifications()
                break;
            case "Security":
                @RenderSecurity()
                break;
            case "Appearance":
                @RenderAppearance()
                break;
