{
    <div class="modal-backdrop" @onclick="CancelConfirm">
        <div class="confirm-dialog" @onclick:stopPropagation>
            <h6>@_confirmTitle</h6>
            <p>@_confirmMessage</p>
            <div class="confirm-actions">
                <button class="btn btn-secondary btn-sm" @onclick="CancelConfirm">Cancel</button>
                <button class="btn btn-danger btn-sm" @onclick="ExecuteConfirm">Confirm</button>
            </div>
        </div>
    </div>
}

